(()=>{'use strict';if(window.__radarPrototypeVersionV215)return;window.__radarPrototypeVersionV215=true;function add(){if(document.getElementById('radarPrototypeVersion'))return true;const postos=document.getElementById('gasBtn')||[...document.querySelectorAll('button')].find(b=>/Postos/i.test(b.textContent||''));if(!postos)return false;const badge=document.createElement('div');badge.id='radarPrototypeVersion';badge.textContent='V 215';badge.style.cssText='display:block;width:max-content;margin:5px auto 0;padding:3px 10px;border-radius:12px;background:rgba(7,19,31,.90);border:1px solid rgba(255,255,255,.20);color:#fff;font:800 12px/1.2 Arial,sans-serif;letter-spacing:.8px;box-shadow:0 2px 8px rgba(0,0,0,.25);pointer-events:none';postos.insertAdjacentElement('afterend',badge);return true}let n=0,t=setInterval(()=>{n++;if(add()||n>200)clearInterval(t)},100)})();